'use client';
import React, { useId } from 'react';
import { Input, InputGroup } from './input.jsx';
import { FieldLabel, FieldDescription } from './field.jsx';
// A start and an end value share one box, so the eye stops once instead of twice. startProps/endProps go to each input.
export function DateRange({ label = '기간', help, error, disabled, startProps = {}, endProps = {} }) {
  const id = useId(); const description = error || help;
  const own = { disabled, 'aria-invalid': error ? true : undefined, 'aria-describedby': description ? `${id}-help` : undefined };
  return <div className="ds-field ds-date-range" data-state={error ? 'error' : disabled ? 'disabled' : undefined}><FieldLabel htmlFor={id}>{label}</FieldLabel><InputGroup><Input placeholder="시작" {...startProps} {...own} id={id} /><span className="ds-input-join" aria-hidden="true">~</span><Input placeholder="끝" {...endProps} {...own} aria-label={`${label} 끝`} /></InputGroup>{description && <FieldDescription id={`${id}-help`}>{description}</FieldDescription>}</div>;
}

import React from 'react';
// look: box (윤곽, the default box) or filled (채움).
export function Input({ look, className = '', ...props }) { return <input {...props} className={`ds-input ${className}`} data-look={look} />; }
// The inputs that keep a helper inside the same box (clear, unit, stepper, password, date range) are built from these two.
export function InputGroup({ className = '', children, ...props }) { return <span {...props} className={`ds-input-group ${className}`}>{children}</span>; }
export function InputTool({ children, ...props }) { return <button type="button" {...props} className="ds-input-tool">{children}</button>; }

'use client';
import React, { useId } from 'react';
import { Input } from './input.jsx';
export function FieldLabel({ htmlFor, children, ...props }) { return <label {...props} htmlFor={htmlFor}>{children}</label>; }
export function FieldDescription({ id, children, ...props }) { return <p {...props} className="ds-help" id={id}>{children}</p>; }
export function Field({ id: suppliedId, label, help, error, state, children, ...props }) {
  const generatedId = useId(); const id = suppliedId || generatedId;
  const description = error || help;
  const inputProps = { ...props, id, 'aria-invalid': error ? true : undefined, 'aria-describedby': [props['aria-describedby'], description ? `${id}-help` : ''].filter(Boolean).join(' ') || undefined };
  return <div className="ds-field" data-state={error ? 'error' : props.disabled ? 'disabled' : state}>
    <FieldLabel htmlFor={id}>{label}</FieldLabel>
    {children ? children(inputProps) : <Input {...inputProps} />}
    {description && <FieldDescription id={`${id}-help`}>{description}</FieldDescription>}
  </div>;
}

